import React, { useEffect, useState, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { toast } from 'sonner';

const SW_LOGO = "data:image/png;base64,";

const LoginForm = () => {
  const { tryLogin, isAuthenticated } = useAuth();
  const [phase, setPhase] = useState('loading'); // 'loading' | 'login'
  const [progress, setProgress] = useState(0);
  const [step, setStep] = useState(0);
  const [empId, setEmpId] = useState('');
  const [password, setPassword] = useState('');
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const canvasRef = useRef(null);
  const STEPS = ['Initializing modules', 'Loading resources', 'Establishing connection', 'Ready'];

  // Loading animation then show login
  useEffect(() => {
    const start = Date.now(), dur = 2800;
    const interval = setInterval(() => {
      const p = Math.min(100, Math.round(((Date.now()-start)/dur)*100));
      setProgress(p);
      setStep(Math.min(3, Math.floor(p/25)));
      if (p >= 100) { clearInterval(interval); setTimeout(() => setPhase('login'), 400); }
    }, 30);
    return () => clearInterval(interval);
  }, []);

  // Particle canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    resize();
    window.addEventListener('resize', resize);
    const particles = Array.from({length:70}, () => ({
      x: Math.random()*canvas.width, y: Math.random()*canvas.height,
      vx: (Math.random()-.5)*.5, vy: (Math.random()-.5)*.5,
      r: Math.random()*1.8+.4,
      c: ['rgba(255,255,255,','rgba(200,230,255,','rgba(147,210,255,'][Math.floor(Math.random()*3)],
    }));
    let raf;
    const draw = () => {
      ctx.fillStyle='rgba(10,37,80,0.15)';
      ctx.fillRect(0,0,canvas.width,canvas.height);
      particles.forEach(p => {
        p.x+=p.vx; p.y+=p.vy;
        if(p.x<0||p.x>canvas.width) p.vx*=-1;
        if(p.y<0||p.y>canvas.height) p.vy*=-1;
        ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
        ctx.fillStyle=p.c+'0.8)'; ctx.fill();
      });
      for(let i=0;i<particles.length;i++) for(let j=i+1;j<particles.length;j++) {
        const dx=particles[i].x-particles[j].x, dy=particles[i].y-particles[j].y, d=Math.hypot(dx,dy);
        if(d<120) { ctx.beginPath(); ctx.moveTo(particles[i].x,particles[i].y); ctx.lineTo(particles[j].x,particles[j].y); ctx.strokeStyle=`rgba(255,255,255,${(1-d/120)*.15})`; ctx.lineWidth=.6; ctx.stroke(); }
      }
      raf=requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(raf); window.removeEventListener('resize', resize); };
  }, []);

  const handleLogin = (e) => {
    e.preventDefault();
    if (!empId.trim()) { setError('Please enter your Employee ID'); return; }
    if (!password.trim()) { setError('Please enter your password'); return; }
    setSubmitting(true); setError('');
    setTimeout(() => {
      const result = tryLogin(empId.trim(), password.trim());
      if (result.success) {
        toast.success('Welcome to SmartDesk', { description: 'Portal ready', duration: 3000 });
      } else {
        setError(result.error || 'Invalid credentials');
        setSubmitting(false);
      }
    }, 600);
  };

  const inp = { background:'rgba(255,255,255,0.1)', border:'1px solid rgba(255,255,255,0.25)', borderRadius:10, padding:'11px 14px', color:'#ffffff', fontFamily:"'DM Sans',sans-serif", fontSize:'.9rem', outline:'none', width:'100%', transition:'border-color .2s' };

  return (
    <div style={{ position:'relative', minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center', overflow:'hidden',
      background:'linear-gradient(135deg,#0a2548 0%,#105da9 45%,#0d3d7a 100%)' }}>

      <canvas ref={canvasRef} style={{ position:'absolute', inset:0, zIndex:0 }}/>

      {/* SW Logo watermark */}
      <div style={{ position:'absolute', inset:0, zIndex:1, display:'flex', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
        <img src={SW_LOGO} alt="" style={{ width:'72%', maxWidth:900, opacity:0.07, filter:'brightness(2) saturate(0)', userSelect:'none' }}/>
      </div>

      {/* Ambient blobs */}
      <div style={{ position:'absolute', width:600, height:600, borderRadius:'50%', background:'radial-gradient(circle,rgba(255,255,255,0.08),transparent)', top:-150, left:-150, filter:'blur(80px)', zIndex:1, pointerEvents:'none' }}/>
      <div style={{ position:'absolute', width:400, height:400, borderRadius:'50%', background:'radial-gradient(circle,rgba(255,255,255,0.06),transparent)', bottom:-100, right:-80, filter:'blur(60px)', zIndex:1, pointerEvents:'none' }}/>

      {/* Card */}
      <div style={{ position:'relative', zIndex:10, width:360, padding:'36px 32px',
        background:'rgba(255,255,255,0.12)', border:'1px solid rgba(255,255,255,0.25)',
        borderRadius:20, backdropFilter:'blur(28px)', WebkitBackdropFilter:'blur(28px)',
        boxShadow:'0 32px 80px rgba(0,0,0,0.35), 0 0 0 1px rgba(255,255,255,0.1)',
        animation:'loginIn 0.5s cubic-bezier(.22,.68,0,1.2)',
      }}>
        <div style={{ position:'absolute', top:0, left:'15%', right:'15%', height:2, background:'linear-gradient(90deg,transparent,rgba(255,255,255,0.9),transparent)', borderRadius:1 }}/>

        {/* Logo */}
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', marginBottom: phase==='login' ? 24 : 28 }}>
          <div style={{ width:64, height:64, borderRadius:16, background:'rgba(255,255,255,0.15)', border:'1px solid rgba(255,255,255,0.3)', display:'flex', alignItems:'center', justifyContent:'center', boxShadow:'0 8px 28px rgba(0,0,0,0.3)', marginBottom:14, animation:'logoFloat 4s ease-in-out infinite' }}>
            <img src="/images/swd-logo.png" alt="SmartDesk" width={46} height={46} style={{ objectFit:'contain', filter:'brightness(0) invert(1)' }}/>
          </div>
          <div style={{ fontFamily:"'Plus Jakarta Sans',sans-serif", fontWeight:800, fontSize:'1.6rem', color:'#ffffff', letterSpacing:'-0.01em' }}>SmartDesk</div>
          <div style={{ fontFamily:"'DM Sans',sans-serif", fontSize:'.78rem', color:'rgba(255,255,255,0.65)', marginTop:4 }}>Smart World Developers · Enterprise Portal</div>
        </div>

        {/* ── LOADING PHASE ── */}
        {phase === 'loading' && (
          <div>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:10 }}>
              <span style={{ fontFamily:"'DM Sans',sans-serif", fontSize:'.78rem', color:'rgba(255,255,255,0.75)' }}>{STEPS[step]}...</span>
              <span style={{ fontFamily:"'Plus Jakarta Sans',sans-serif", fontWeight:800, fontSize:'.82rem', color:'#ffffff' }}>{progress}%</span>
            </div>
            <div style={{ height:6, borderRadius:6, background:'rgba(255,255,255,0.15)', overflow:'hidden', marginBottom:18 }}>
              <div style={{ height:'100%', borderRadius:6, background:'linear-gradient(90deg,#ffffff,rgba(200,230,255,.9))', width:`${progress}%`, transition:'width .06s linear', boxShadow:'0 0 14px rgba(255,255,255,.6)' }}/>
            </div>
            <div style={{ display:'flex', justifyContent:'center', gap:8 }}>
              {STEPS.map((_,i) => (
                <div key={i} style={{ width:i===step?22:7, height:7, borderRadius:4, background:i<=step?'rgba(255,255,255,.9)':'rgba(255,255,255,.2)', transition:'all .4s', boxShadow:i===step?'0 0 10px rgba(255,255,255,.8)':'none' }}/>
              ))}
            </div>
            <div style={{ marginTop:22, textAlign:'center', fontFamily:"'DM Sans',sans-serif", fontSize:'.65rem', color:'rgba(255,255,255,.45)' }}>Auto-login enabled · Secured connection</div>
          </div>
        )}

        {/* ── LOGIN PHASE ── */}
        {phase === 'login' && (
          <form onSubmit={handleLogin} style={{ display:'flex', flexDirection:'column', gap:14 }}>
            <div>
              <label style={{ fontFamily:"'Plus Jakarta Sans',sans-serif", fontSize:'.7rem', fontWeight:700, color:'rgba(255,255,255,0.7)', letterSpacing:'.1em', textTransform:'uppercase', display:'block', marginBottom:6 }}>Employee ID</label>
              <input
                type="text" placeholder="Enter your Employee ID (e.g. 81096)"
                value={empId} onChange={e=>{setEmpId(e.target.value);setError('');}}
                style={inp}
                onFocus={e=>e.target.style.borderColor='rgba(255,255,255,0.6)'}
                onBlur={e=>e.target.style.borderColor='rgba(255,255,255,0.25)'}
                autoFocus
              />
            </div>
            <div>
              <label style={{ fontFamily:"'Plus Jakarta Sans',sans-serif", fontSize:'.7rem', fontWeight:700, color:'rgba(255,255,255,0.7)', letterSpacing:'.1em', textTransform:'uppercase', display:'block', marginBottom:6 }}>Password</label>
              <div style={{ position:'relative' }}>
                <input
                  type={showPw?'text':'password'} placeholder="Smart@(reverse of your ID)"
                  value={password} onChange={e=>{setPassword(e.target.value);setError('');}}
                  style={{ ...inp, paddingRight:44 }}
                  onFocus={e=>e.target.style.borderColor='rgba(255,255,255,0.6)'}
                  onBlur={e=>e.target.style.borderColor='rgba(255,255,255,0.25)'}
                />
                <button type="button" onClick={()=>setShowPw(s=>!s)}
                  style={{ position:'absolute', right:12, top:'50%', transform:'translateY(-50%)', background:'none', border:'none', color:'rgba(255,255,255,0.5)', cursor:'pointer', padding:0, fontSize:16 }}>
                  {showPw ? '🙈' : '👁'}
                </button>
              </div>
              <div style={{ fontFamily:"'DM Sans',sans-serif", fontSize:'.68rem', color:'rgba(255,255,255,0.4)', marginTop:5 }}>
                Format: Smart@(reverse of Employee ID) — e.g. ID 81096 → Smart@69018
              </div>
            </div>

            {error && (
              <div style={{ background:'rgba(239,68,68,0.2)', border:'1px solid rgba(239,68,68,0.4)', borderRadius:8, padding:'9px 13px', fontFamily:"'DM Sans',sans-serif", fontSize:'.8rem', color:'#fca5a5' }}>
                ⚠ {error}
              </div>
            )}

            <button type="submit" disabled={submitting}
              style={{ marginTop:4, background: submitting ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.22)', border:'1px solid rgba(255,255,255,0.4)', borderRadius:10, padding:'12px', color:'#ffffff', fontFamily:"'Plus Jakarta Sans',sans-serif", fontWeight:700, fontSize:'.9rem', cursor:submitting?'wait':'pointer', transition:'all .2s', boxShadow: submitting?'none':'0 4px 20px rgba(0,0,0,0.2)' }}>
              {submitting ? 'Signing in...' : 'Sign In →'}
            </button>

            <div style={{ textAlign:'center', fontFamily:"'DM Sans',sans-serif", fontSize:'.68rem', color:'rgba(255,255,255,0.35)', marginTop:4 }}>
              Admin login: use <span style={{ color:'rgba(255,255,255,0.6)', fontWeight:600 }}>admin</span> / <span style={{ color:'rgba(255,255,255,0.6)', fontWeight:600 }}>SmartWorld@2026</span>
            </div>
          </form>
        )}
      </div>

      <style>{`
        @keyframes loginIn { from{opacity:0;transform:translateY(20px) scale(.97)} to{opacity:1;transform:translateY(0) scale(1)} }
        @keyframes logoFloat { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-6px)} }
        input::placeholder { color: rgba(255,255,255,0.35) !important; }
      `}</style>
    </div>
  );
};

export default LoginForm;
